1	package darksafe
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"testing"
12	)
13	
14	// This file covers the command-line contract of fault-domain spreading
15	// (spreadBy): the library rules already have unit tests in plan_test.go; here
16	// the same guarantees are observed through `darksafe plan <file>` exactly as a
17	// user drives it — a config file on disk, JSON on stdout, errors on stderr and
18	// process exit codes. Everything runs offline: the binary never connects to a
19	// cluster or performs a release.
20	
21	// cliPlan mirrors the JSON shape of a printed ReleasePlan.
22	type cliPlan struct {
23		App      cliApp        `json:"app"`
24		Batches  []cliBatch    `json:"batches"`
25		Excluded []cliExcluded `json:"excluded"`
26	}
27	
28	type cliApp struct {
29		Name     string `json:"name"`
30		Revision string `json:"revision"`
31		Image    string `json:"image"`
32	}
33	
34	type cliBatch struct {
35		Index    int      `json:"index"`
36		Clusters []string `json:"clusters"`
37	}
38	
39	type cliExcluded struct {
40		ID     string `json:"id"`
41		Reason string `json:"reason"`
42	}
43	
44	// writePlanDoc stores doc in a fresh temp directory and returns its path.
45	func writePlanDoc(t *testing.T, doc string) string {
46		t.Helper()
47		path := filepath.Join(t.TempDir(), "plan.json")
48		if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
49			t.Fatal(err)
50		}
51		return path
52	}
53	
54	// decodeCLIPlan requires stdout to hold exactly one complete JSON plan and
55	// nothing after it: success means stdout contains only the plan.
56	func decodeCLIPlan(t *testing.T, stdout string) cliPlan {
57		t.Helper()
58		dec := json.NewDecoder(strings.NewReader(stdout))
59		var p cliPlan
60		if err := dec.Decode(&p); err != nil {
61			t.Fatalf("stdout is not a parseable JSON plan: %v; stdout=%q", err, stdout)
62		}
63		if err := dec.Decode(&struct{}{}); err != io.EOF {
64			t.Fatalf("stdout carries data after the plan: %q", stdout)
65		}
66		return p
67	}
68	
69	// assertBatches checks batch numbering, size, ascending order, domain
70	// uniqueness per batch and that every selected ID appears exactly once.
71	func assertSpreadBatches(t *testing.T, p cliPlan, want [][]string, domains map[string]string, batchSize int) {
72		t.Helper()
73		if len(p.Batches) != len(want) {
74			t.Fatalf("got %d batches %v, want %d batches %v", len(p.Batches), p.Batches, len(want), want)
75		}
76		seen := map[string]int{}
77		for i, w := range want {
78			b := p.Batches[i]
79			if b.Index != i+1 {
80				t.Fatalf("batch %d has index %d, want %d", i, b.Index, i+1)
81			}
82			if len(b.Clusters) > batchSize {
83				t.Fatalf("batch %d holds %d clusters, batchSize is %d", i+1, len(b.Clusters), batchSize)
84			}
85			if strings.Join(b.Clusters, ",") != strings.Join(w, ",") {
86				t.Fatalf("batch %d = %v, want %v", i+1, b.Clusters, w)
87			}
88			if !sort.StringsAreSorted(b.Clusters) {
89				t.Fatalf("batch %d is not ascending: %v", i+1, b.Clusters)
90			}
91			usedDomain := map[string]string{}
92			for _, id := range b.Clusters {
93				if prev, dup := seen[id]; dup {
94					t.Fatalf("cluster %q appears in batch %d and again in batch %d", id, prev, i+1)
95				}
96				seen[id] = i + 1
97				d, known := domains[id]
98				if !known {
99					t.Fatalf("cluster %q in plan but no expected domain", id)
100				}
101				if other, conflict := usedDomain[d]; conflict {
102					t.Fatalf("batch %d contains two clusters of domain %q: %q and %q", i+1, d, other, id)
103				}
104				usedDomain[d] = id
105			}
106		}
107	}
108	
109	// TestPlanCLI_SpreadByFullPlan drives the whole contract through the CLI:
110	// complete parseable JSON plan, app/revision/image echoed from the input,
111	// fault-domain-aware batching, ascending excluded list with existing reasons,
112	// exit code 0, plan-only stdout and an empty stderr. Candidates are listed out
113	// of order in the file; that must not change any of the results.
114	func TestPlanCLI_SpreadByFullPlan(t *testing.T) {
115		doc := `{
116	  "app": "payments",
117	  "revision": "2026.10.0-r3",
118	  "image": "registry.example.net/payments:2026.10.0-r3",
119	  "batchSize": 3,
120	  "spreadBy": "zone",
121	  "include": [{"zone": "z1"}, {"zone": "z2"}, {"zone": "z3"}],
122	  "exclude": [{"env": "temp"}],
123	  "clusters": [
124	    {"id": "c-d", "tags": {"zone": "z3"}},
125	    {"id": "x2", "tags": {"env": "temp"}},
126	    {"id": "c-b", "tags": {"zone": "z1"}},
127	    {"id": "x1", "tags": {"env": "dev"}},
128	    {"id": "off", "disabled": true},
129	    {"id": "c-e", "tags": {"zone": "z2"}},
130	    {"id": "c-a", "tags": {"zone": "z1"}},
131	    {"id": "c-c", "tags": {"zone": "z2"}}
132	  ]
133	}`
134		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
135		if code != 0 {
136			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
137		}
138		if stderr != "" {
139			t.Fatalf("expected empty stderr on success, got %q", stderr)
140		}
141	
142		p := decodeCLIPlan(t, stdout)
143		if p.App.Name != "payments" || p.App.Revision != "2026.10.0-r3" ||
144			p.App.Image != "registry.example.net/payments:2026.10.0-r3" {
145			t.Fatalf("app info not echoed from input: %+v", p.App)
146		}
147	
148		// Sorted selection is c-a,c-b (z1), c-c,c-e (z2), c-d (z3). Batch 1 takes
149		// the smallest IDs that fit: c-a(z1), c-c(z2), c-d(z3); c-b and c-e are
150		// deferred by domain conflicts and form batch 2.
151		domains := map[string]string{
152			"c-a": "z1", "c-b": "z1",
153			"c-c": "z2", "c-e": "z2",
154			"c-d": "z3",
155		}
156		assertSpreadBatches(t, p,
157			[][]string{{"c-a", "c-c", "c-d"}, {"c-b", "c-e"}},
158			domains, 3)
159	
160		wantExcluded := []cliExcluded{
161			{ID: "off", Reason: ReasonDisabled},
162			{ID: "x1", Reason: ReasonIncludeNotMatched},
163			{ID: "x2", Reason: ReasonExcludeMatched},
164		}
165		if len(p.Excluded) != len(wantExcluded) {
166			t.Fatalf("excluded = %+v, want %+v", p.Excluded, wantExcluded)
167		}
168		for i, w := range wantExcluded {
169			if p.Excluded[i] != w {
170				t.Fatalf("excluded[%d] = %+v, want %+v", i, p.Excluded[i], w)
171			}
172		}
173	}
174	
175	// TestPlanCLI_SpreadByConflictDefersButDoesNotBlock isolates the core rule:
176	// a same-domain conflict defers that cluster to a later batch, but later
177	// clusters of other domains still enter the current batch, and each batch is
178	// filled from the smallest still-unscheduled ID that can enter it.
179	func TestPlanCLI_SpreadByConflictDefersButDoesNotBlock(t *testing.T) {
180		doc := `{
181	  "app": "app", "revision": "r1", "image": "img",
